import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    num_cols = ['left', 'tenure_months', 'salary', 'performance_score']
    for col in num_cols:
        s = df[col].dropna()
        result['eda_summary'][col] = {
            'mean': float(s.mean()), 'std': float(s.std()),
            'min': float(s.min()), 'max': float(s.max()),
            'median': float(s.median()), 'count': int(s.count())
        }
except Exception:
    pass

try:
    import numpy as np
    from scipy import stats
    numeric_df = df[num_cols].dropna()
    pairs = [(a, b) for i, a in enumerate(num_cols) for b in num_cols[i+1:]]
    for a, b in pairs:
        r, _ = stats.pearsonr(numeric_df[a], numeric_df[b])
        if abs(r) >= 0.2:
            result['correlations'][f'{a}__{b}'] = round(float(r), 4)
except Exception:
    pass

try:
    seg_col = 'department'
    top_depts = df[seg_col].value_counts().index.tolist()
    for metric in ['left', 'tenure_months', 'salary', 'performance_score']:
        grp = df.groupby(seg_col)[metric].mean()
        result['segments'].append({
            'segment_column': seg_col, 'metric_column': metric,
            'aggregation': 'mean', 'label': None,
            'results': [{'name': str(k), 'value': round(float(v), 4)} for k, v in grp.items()]
        })
    attrition_grp = df.groupby(seg_col)['left'].agg(['sum', 'count'])
    result['segments'].append({
        'segment_column': seg_col, 'metric_column': 'left',
        'aggregation': 'ratio', 'label': 'attrition_rate',
        'results': [{'name': str(k), 'value': round(float(row['sum'] / row['count']), 4)}
                    for k, row in attrition_grp.iterrows()]
    })
except Exception:
    pass

try:
    import numpy as np
    anomaly_records = []
    for col in num_cols:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        shift = max(0, -s.min()) + 1 if s.min() < 0 else 0
        vals = np.log1p(s + shift) if abs(skew) > 2 else s
        q1, q3 = vals.quantile(0.25), vals.quantile(0.75)
        iqr = q3 - q1
        lo3, hi3 = q1 - 3 * iqr, q3 + 3 * iqr
        lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
        lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr
        mask = (vals < lo3) | (vals > hi3)
        if mask.sum() / len(s) > 0.05:
            result['anomalies'].append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': 'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-value flagging skipped'
            })
            continue
        flagged = df.loc[mask.index[mask], col]
        if abs(skew) > 2:
            orig_lo = float(np.expm1(lo3) - shift)
            orig_hi = float(np.expm1(hi3) - shift)
        else:
            orig_lo, orig_hi = float(lo3), float(hi3)
        exp_range = f'[{orig_lo:.2f}, {orig_hi:.2f}]'
        for idx, val in flagged.items():
            lv = np.log1p(val + shift) if abs(skew) > 2 else val
            if lv < lo5 or lv > hi5:
                sev = 'critical'
            elif lv < lo4 or lv > hi4:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': float(val),
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {float(val):.4g} lies outside expected range {exp_range}'
            })
    anomaly_records.sort(key=lambda x: ['medium','high','critical'].index(x['severity']) if x['severity'] in ['medium','high','critical'] else -1, reverse=True)
    result['anomalies'].extend(anomaly_records[:25])
except Exception:
    pass

try:
    import numpy as np
    df['hire_date_dt'] = pd.to_datetime(df['hire_date'], errors='coerce')
    df['hire_ym'] = df['hire_date_dt'].dt.to_period('M')
    for metric in ['salary', 'tenure_months', 'performance_score']:
        monthly = df.groupby('hire_ym')[metric].mean().sort_index()
        if len(monthly) < 2:
