    anomaly_records = []
    for col in num_cols:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        shift = max(0, -s.min()) + 1 if s.min() < 0 else 0
        vals = np.log1p(s + shift) if abs(skew) > 2 else s
        q1, q3 = vals.quantile(0.25), vals.quantile(0.75)
        iqr = q3 - q1
        lo3, hi3 = q1 - 3 * iqr, q3 + 3 * iqr
        lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
        lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr
        mask = (vals < lo3) | (vals > hi3)
        if mask.sum() / len(s) > 0.05:
            result['anomalies'].append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': 'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-value flagging skipped'
            })
            continue
        flagged = df.loc[mask.index[mask], col]
        if abs(skew) > 2:
            orig_lo = float(np.expm1(lo3) - shift)
            orig_hi = float(np.expm1(hi3) - shift)
        else:
            orig_lo, orig_hi = float(lo3), float(hi3)
        exp_range = f'[{orig_lo:.2f}, {orig_hi:.2f}]'
        for idx, val in flagged.items():
            lv = np.log1p(val + shift) if abs(skew) > 2 else val
            if lv < lo5 or lv > hi5:
                sev = 'critical'
            elif lv < lo4 or lv > hi4:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': float(val),
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {float(val):.4g} lies outside expected range {exp_range}'
            })
    anomaly_records.sort(key=lambda x: ['medium','high','critical'].index(x['severity']) if x['severity'] in ['medium','high','critical'] else -1, reverse=True)
    result['anomalies'].extend(anomaly_records[:25])
except Exception:
    pass

try:
    import numpy as np
    df['hire_date_dt'] = pd.to_datetime(df['hire_date'], errors='coerce')
    df['hire_ym'] = df['hire_date_dt'].dt.to_period('M')
    for metric in ['salary', 'tenure_months', 'performance_score']:
        monthly = df.groupby('hire_ym')[metric].mean().sort_index()
        if len(monthly) < 2:
            continue
        pct = float((monthly.iloc[-1] - monthly.iloc[-2]) / monthly.iloc[-2] * 100) if monthly.iloc[-2] != 0 else 0.0
        direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
        result['trends'].append({
            'column': metric, 'period': 'MoM', 'direction': direction,
            'pct_change': round(pct, 4), 'segment': None
        })
    rolling = df.set_index('hire_date_dt').sort_index()[['salary']].dropna()
    if len(rolling) >= 7:
        roll7 = rolling['salary'].rolling('7D').mean().dropna()
        if len(roll7) >= 2:
            pct7 = float((roll7.iloc[-1] - roll7.iloc[-2]) / roll7.iloc[-2] * 100) if roll7.iloc[-2] != 0 else 0.0
            result['trends'].append({
                'column': 'salary', 'period': '7d_rolling',
                'direction': 'up' if pct7 > 1 else ('down' if pct7 < -1 else 'flat'),
                'pct_change': round(pct7, 4), 'segment': None
            })
