    import numpy as np
    from scipy import stats
    anomaly_records = []
    for col in num_cols:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = -s.min() if s.min() < 0 else 0
            s_t = np.log1p(s + shift)
        else:
            s_t = s
            shift = 0
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo, hi = q1 - 3 * iqr, q3 + 3 * iqr
        flagged = s_t[(s_t < lo) | (s_t > hi)]
        if len(flagged) / len(s_t) > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': 'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme values are natural, not anomalies'
            })
            continue
        if abs(skew) > 2:
            lo_orig = float(np.expm1(lo) - shift)
            hi_orig = float(np.expm1(hi) - shift)
        else:
            lo_orig, hi_orig = float(lo), float(hi)
        for idx in flagged.index:
            raw_val = float(df.loc[idx, col])
            s_val = float(s_t[idx])
            if s_val > q3 + 5 * iqr or s_val < q1 - 5 * iqr:
                sev = 'critical'
            elif s_val > q3 + 4 * iqr or s_val < q1 - 4 * iqr:
                sev = 'high'
            else:
                sev = 'medium'
            exp_range = f'[{lo_orig:.2f}, {hi_orig:.2f}]'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': raw_val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {raw_val} lies outside expected range {exp_range}'
            })
    anomaly_records = anomaly_records[:25]
    result['anomalies'].extend(anomaly_records)
