        orig_q3 = s.quantile(0.75)
        orig_iqr = orig_q3 - orig_q1
        orig_lo = orig_q1 - 3 * orig_iqr
        orig_hi = orig_q3 + 3 * orig_iqr
        for idx in flagged.index:
            orig_val = df.loc[idx, col]
            if orig_val > orig_q3 + 5 * orig_iqr or orig_val < orig_q1 - 5 * orig_iqr:
                sev = 'critical'
            elif orig_val > orig_q3 + 4 * orig_iqr or orig_val < orig_q1 - 4 * orig_iqr:
                sev = 'high'
