            exp_range = f'{round(float(orig_lo), 2)} to {round(float(orig_hi), 2)}'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': float(orig_val),
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {float(orig_val)} lies outside expected range {exp_range}'
