        skew = float(s.skew())
        if abs(skew) > 2:
            shift = -s.min() if s.min() < 0 else 0
            s_t = (s + shift).apply(lambda x: float('nan') if x <= 0 else x).dropna()
            import numpy as np
            s_t = s_t.apply(lambda x: float(np.log1p(x)))
        else:
            s_t = s
        q1 = s_t.quantile(0.25)
        q3 = s_t.quantile(0.75)
        iqr = q3 - q1
        lo = q1 - 3 * iqr
        hi = q3 + 3 * iqr
        flagged = s_t[(s_t < lo) | (s_t > hi)]
        if len(flagged) / len(s_t) > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': 'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme values are natural, not anomalies'
            })
            continue
        orig_q1 = s.quantile(0.25)
        orig_q3 = s.quantile(0.75)
        orig_iqr = orig_q3 - orig_q1
        orig_lo = orig_q1 - 3 * orig_iqr
        orig_hi = orig_q3 + 3 * orig_iqr
        for idx in flagged.index:
            orig_val = df.loc[idx, col]
            if orig_val > orig_q3 + 5 * orig_iqr or orig_val < orig_q1 - 5 * orig_iqr:
                sev = 'critical'
            elif orig_val > orig_q3 + 4 * orig_iqr or orig_val < orig_q1 - 4 * orig_iqr:
                sev = 'high'
            else:
                sev = 'medium'
            exp_range = f'{round(float(orig_lo), 2)} to {round(float(orig_hi), 2)}'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': float(orig_val),
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {float(orig_val)} lies outside expected range {exp_range}'
            })
            if len(anomaly_records) >= 25:
                break
        if len(anomaly_records) >= 25:
            break
    result['anomalies'] = anomaly_records[:25]
except Exception:
