    for col in anomaly_cols:
        series = df_counted[col].dropna()
        if series.nunique() < 5:
            continue
        skew = float(series.skew())
        if abs(skew) > 2:
            shift = max(0, -series.min())
            transformed = np.log1p(series + shift)
        else:
            transformed = series.copy()
            shift = 0
        q1 = transformed.quantile(0.25)
        q3 = transformed.quantile(0.75)
        iqr = q3 - q1
        lo = q1 - 3 * iqr
        hi = q3 + 3 * iqr
        mask = (transformed < lo) | (transformed > hi)
        flagged_pct = mask.sum() / len(series)
        if flagged_pct > 0.05:
            all_anomalies.append({
                'column': col,
                'row_index': None,
                'value': None,
                'expected_range': 'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f"{col} is heavy-tailed; extreme-value flagging suppressed"
            })
            continue
        flagged_idx = series[mask].index
        lo_orig = float(np.expm1(lo) - shift) if abs(skew) > 2 else float(lo)
        hi_orig = float(np.expm1(hi) - shift) if abs(skew) > 2 else float(hi)
        exp_range = f"[{lo_orig:.2f}, {hi_orig:.2f}]"
        for idx in flagged_idx:
            val = float(series[idx])
            t_val = float(transformed[idx])
            if t_val > q3 + 5 * iqr or t_val < q1 - 5 * iqr:
                sev = 'critical'
            elif t_val > q3 + 4 * iqr or t_val < q1 - 4 * iqr:
                sev = 'high'
            else:
                sev = 'medium'
            all_anomalies.append({
                'column': col,
                'row_index': int(idx),
                'value': val,
                'expected_range': exp_range,
                'severity': sev,
                'explanation': f"{col} value {val:.2f} lies outside expected range {exp_range}"
            })
    all_anomalies = all_anomalies[:25]
